def label(kind):return {'theory':'Theory only','zero-left':'Zero-left transfer','both':'Both theorem transfers','setup-0':'Zero-left setup proof','setup-1':'Left-successor setup proof'}[kind]
def panel(o,i):
    path=OUT/('commutativity-'+o['kind']+'.p');mapping=load(path.with_suffix('.mapping.json'));text=(OUT/(o['stem']+'.tstp')).read_text();good=o['proof_check']['result'];rs=records(text);numbers={r['name']:j+1 for j,r in enumerate(rs)}
    aliases={name:'w_{'+str(j+1)+'}' for j,name in enumerate(good['introductions'])};mapping={**mapping,'witness_names':aliases}
    parts=['<article class="proof-panel" id="proof-'+str(i)+'"'+(' hidden' if i else '')+'><p><strong>'+label(o['kind'])+'</strong> · '+num(len(rs))+' actual returned lines. Used transferred lemma inputs: '+(', '.join('<code>'+esc(x)+'</code>' for x in o['used_lemma_inputs']) or 'none')+'.</p>']
    parts.append('<details><summary>Fresh witness aliases declared in this run</summary><table><tr><th>Display alias</th><th>Actual E symbol</th><th>Arity</th></tr>')
