    schemas=''.join('<details><summary><code>'+s['id']+'</code> · induction variable '+math(s['variable'])+' · parameters '+(', '.join(math(v) for v in s['parameters']) or 'none')+'</summary><div class="formula">'+formula(s['formula'])+'</div><p>Predicate: '+formula(s['template'])+'.</p></details>' for s in bundle['schemas'])
    costs=[('Source/input preparation',plan['preparation_seconds']),('Pre-E independent input/native-boundary binding',load(OUT/'input-audit.json')['seconds']),('Fresh fixture reruns',summary['fixtures']['seconds']),('Two fresh setup E binaries',sum(o['e_measurement']['wall_seconds'] for o in summary['setup'])),('Two setup complete-check workers',sum(o['proof_check']['process_wall_seconds'] for o in summary['setup'])),('Two setup full-replay workers',sum(o['proof_replay']['process_wall_seconds'] for o in summary['setup'])),('Independent complete pre-target gate',summary['pre_run_gate_seconds']),('Six target E binaries',sum(o['e_measurement']['wall_seconds'] for o in summary['observations'])),('Six target complete-check workers',sum(o['proof_check']['process_wall_seconds'] for o in summary['observations'])),('Six target full-replay workers',sum(o['proof_replay']['process_wall_seconds'] for o in summary['observations'])),('Whole capped producer, including setup and orchestration',summary['seconds']),('Independent post-result complete replay/source audit',audit['seconds']),('Post-result actual-certificate corruption audit',mut['seconds'])]
    costrows=''.join('<tr><td>'+esc(a)+'</td><td>'+seconds(b)+'</td></tr>' for a,b in costs)
