    compact=dict(status='passed_complete_six_target_external_control',scope=plan['scope'],plan_sha256=sha((OUT/'plan.json').read_bytes()),producer_seconds=summary['seconds'],preparation_seconds=plan['preparation_seconds'],input_audit_seconds=load(OUT/'input-audit.json')['seconds'],complete_audit_seconds=audit['seconds'],mutation_audit_seconds=mut['seconds'],proof_census=census,actual_corruptions=len(mut['corruptions']),instances=5,input_entries=[8,9,10],setup_proofs=2,target_proofs=6,unknowns=0,costs=costs,observations=[])
    for o in observations:compact['observations'].append(dict(kind=o['kind'],repetition=o.get('repetition'),proof_steps=o['proof_steps'],used_lemma_inputs=o['used_lemma_inputs'],e_seconds=o['e_measurement']['wall_seconds'],check_seconds=o['proof_check']['process_wall_seconds'],replay_seconds=o['proof_replay']['process_wall_seconds'],e_peak_rss_bytes=o['e_measurement']['peak_rss_bytes'],checker_peak_rss_bytes=o['proof_check']['peak_rss_bytes'],output_sha256=o['output_sha256']))
    (DOC/(PREFIX+'.html')).write_text(page);(DOC/(PREFIX+'_data.json.gz')).write_bytes(gzip.compress((json.dumps(evidence,separators=(',',':'))+'\n').encode(),mtime=0))
    for suffix,x in [('plan',plan),('summary',compact),('audit',audit),('mutations',mut)]:dump(DOC/(PREFIX+'_'+suffix+'.json'),x)
    paths=[DOC/(PREFIX+x) for x in ('.html','_data.json.gz','_plan.json','_summary.json','_audit.json','_mutations.json')]+sorted(HERE.glob('external_commutativity_*.py'))
    manifest=dict(status='exported_awaiting_reader_check_and_root_publication',files=[dict(path=str(p.relative_to(ROOT)),sha256=sha(p.read_bytes()),bytes=p.stat().st_size) for p in paths],proposed_url='https://liuyao12.github.io/geometric-tree-search/docs/research/gcts-rl-renewal/'+PREFIX+'.html?v=20261011-ec1#reader',source_scope='Measurement sources were frozen before E; report, fresh reproduction and actual-certificate mutation sources are separately post-result authored reporting/audit tools.',published_by_child=False)
    dump(OUT/'export.json',manifest);print(json.dumps(dict(files=len(paths),lines=census['lines'],html_bytes=(DOC/(PREFIX+'.html')).stat().st_size)),flush=True)
